using System;
using System.Collections.Generic;
using System.Diagnostics;
using System.IO;
using System.Text;
using Velocity;

static class VelocityTests
{
    static int passed,failed;static StringBuilder xml=new StringBuilder();
    static void Check(bool ok,string message){if(!ok)throw new Exception(message);}
    static void Near(float a,float b,float tolerance,string message){Check(Math.Abs(a-b)<=tolerance,message+" expected "+b+", got "+a);}
    static void Test(string name,Action action){var watch=Stopwatch.StartNew();try{action();passed++;Console.WriteLine("PASS "+name);xml.AppendLine("<testcase name=\""+name+"\" time=\""+watch.Elapsed.TotalSeconds.ToString(System.Globalization.CultureInfo.InvariantCulture)+"\" />");}catch(Exception e){failed++;Console.WriteLine("FAIL "+name+": "+e.Message);xml.AppendLine("<testcase name=\""+name+"\"><failure>"+System.Security.SecurityElement.Escape(e.ToString())+"</failure></testcase>");}}
    static World Empty(){var w=new World(0);w.Stage.Enemies.Clear();w.Stage.Walls.RemoveRange(4,w.Stage.Walls.Count-4);w.Player=new V(0,0);return w;}
    static void Tick(World w,int n,V input,bool fire=false,bool dash=false){for(int i=0;i<n;i++)w.Tick(Rules.Step,input,new V(1,0),fire,dash&&i==0,false,false);}
    static bool Reachable(Stage s,V target)
    {
        const float cell=.5f;const int width=105,height=65;bool[,] seen=new bool[width,height];var q=new Queue<V>();q.Enqueue(s.Spawn);int sx=(int)((s.Spawn.X+26)/cell),sy=(int)((s.Spawn.Y+16)/cell);seen[sx,sy]=true;
        while(q.Count>0){V p=q.Dequeue();if((p-target).Length<.8f)return true;foreach(V d in new[]{new V(cell,0),new V(-cell,0),new V(0,cell),new V(0,-cell)}){V n=p+d;int x=(int)Math.Round((n.X+26)/cell),y=(int)Math.Round((n.Y+16)/cell);if(x<0||x>=width||y<0||y>=height||seen[x,y]||s.Blocked(n,Rules.Radius+.03f))continue;seen[x,y]=true;q.Enqueue(n);}}
        return false;
    }
    public static int Main(string[] args)
    {
        Test("speed reaches 20 units within 67ms",()=>{var w=Empty();Tick(w,8,new V(1,0));Near(w.Velocity.Length,20,.01f,"running speed");});
        Test("diagonal speed is normalized",()=>{var a=Empty();var b=Empty();Tick(a,60,new V(1,0));Tick(b,60,new V(1,1));Near(a.Velocity.Length,b.Velocity.Length,.001f,"diagonal exploit");});
        Test("release stops within 67ms",()=>{var w=Empty();Tick(w,30,new V(1,0));Tick(w,8,new V());Near(w.Velocity.Length,0,.001f,"braking");});
        Test("direction reversal is responsive",()=>{var w=Empty();Tick(w,20,new V(1,0));Tick(w,20,new V(-1,0));Near(w.Velocity.X,-20,.01f,"reversal");});
        Test("dash speed is more than 3x running",()=>{var w=Empty();Tick(w,1,new V(1,0),false,true);Near(w.Velocity.Length,64,.01f,"dash");Check(w.Velocity.Length/Rules.Speed>3,"speed ratio");});
        Test("dash travels eight units in exactly fifteen ticks",()=>{var w=Empty();Tick(w,15,new V(1,0),false,true);Near(w.Player.X,8,.01f,"dash distance");Check(w.DashLeft==0,"extra dash frame");});
        Test("dash retains steering input after finish",()=>{var w=Empty();Tick(w,15,new V(1,0),false,true);Tick(w,30,new V(0,1));Near(w.Velocity.Y,20,.01f,"steering");Near(w.Velocity.X,0,.01f,"momentum decays");});
        Test("two dash charges and automatic recharge",()=>{var w=Empty();Tick(w,18,new V(),false,true);Tick(w,18,new V(),false,true);Check(w.Charges==0,"must spend two charges");Tick(w,90,new V());Check(w.Charges>=1,"must recharge");});
        Test("dash input buffers across active dash",()=>{var w=Empty();Tick(w,14,new V(1,0),false,true);w.Tick(Rules.Step,new V(0,1),new V(1,0),false,true,false,false);Tick(w,6,new V(0,1));Check(w.DashLeft>0&&w.DashDirection.Y>.9f,"second dash was lost");});
        Test("exhausted dash buffer expires",()=>{var w=Empty();w.Charges=0;w.RechargeClock=0;Tick(w,1,new V(),false,true);Tick(w,30,new V());Near(w.DashBuffer,0,.0001f,"buffer expiration");});
        Test("focus speed is deliberate precision",()=>{var w=Empty();for(int i=0;i<40;i++)w.Tick(Rules.Step,new V(1,0),new V(1,0),false,false,true,false);Near(w.Velocity.Length,8,.01f,"focus");});
        Test("swept dash cannot tunnel thin wall",()=>{var w=Empty();w.Stage.Walls.Add(new Wall(1,0,.08f,8));Tick(w,17,new V(1,0),false,true);Check(w.Player.X<1-.04f-Rules.Radius+.001f,"wall tunneled "+w.Player.X);});
        Test("wall sliding preserves tangent travel",()=>{var w=Empty();w.Stage.Walls.Add(new Wall(1,0,.2f,20));Tick(w,50,new V(1,1));Check(w.Player.Y>3,"stuck on wall");Check(w.Player.X<1-.1f-Rules.Radius+.001f,"inside wall");});
        Test("boundary holds maximum dash speed",()=>{var w=Empty();w.Player=new V(25,0);Tick(w,17,new V(1,0),false,true);Check(w.Player.X<26-Rules.Radius+.001f,"escaped arena");});
        Test("high speed projectile hits target between frames",()=>{var w=Empty();var e=new Enemy(new V(1,0),1,3,100);w.Stage.Enemies.Add(e);w.AddShot(new V(-1,0),new V(1,0),600,true);Tick(w,1,new V());Check(e.HP==2,"projectile tunneled target");});
        Test("nearest wall shields enemy from bullet",()=>{var w=Empty();w.Stage.Walls.Add(new Wall(0,0,.1f,4));w.Player=new V(-5,0);var e=new Enemy(new V(1,0),1,3,100);w.Stage.Enemies.Add(e);w.AddShot(new V(-1,0),new V(1,0),600,true);Tick(w,1,new V());Check(e.HP==3&&w.Shots.Count==0,"wall priority");});
        Test("bullets hit nearest enemy only",()=>{var w=Empty();var a=new Enemy(new V(1,0),1,3,100);var b=new Enemy(new V(2,0),1,3,100);w.Stage.Enemies.Add(b);w.Stage.Enemies.Add(a);w.AddShot(new V(-1,0),new V(1,0),600,true);Tick(w,1,new V());Check(a.HP==2&&b.HP==3,"ordering");});
        Test("dash protects from hostile damage",()=>{var w=Empty();w.DashLeft=.1f;w.Damage();Check(w.HP==2,"dash immunity");});
        Test("last dash tick retains full bullet immunity",()=>{var w=Empty();w.DashLeft=Rules.Step*.5f;w.DashDirection=new V(1,0);w.AddShot(new V(Rules.DashSpeed*Rules.Step,0),new V(),0,false);Tick(w,1,new V(1,0));Check(w.HP==2&&w.DashLeft==0,"last tick lost immunity");});
        Test("damage grace prevents one frame double hit",()=>{var w=Empty();w.Damage();w.Damage();Check(w.HP==1,"duplicate damage");});
        Test("nightmare is one hit",()=>{var w=new World(0,true);w.Damage();Check(w.State==RunState.Dead,"nightmare death");});
        Test("death is terminal and no late win",()=>{var w=Empty();w.HP=1;w.Damage();V p=w.Player;Tick(w,60,new V(1,0),true,true);Near(w.Time,0,.001f,"dead timer");Near((w.Player-p).Length,0,.001f,"dead movement");});
        Test("zero dt does not process input",()=>{var w=Empty();w.Tick(0,new V(1,0),new V(1,0),true,true,false,false);Check(w.Shots.Count==0&&w.Charges==2,"zero dt advanced");});
        Test("time limit cannot be bypassed",()=>{var w=Empty();w.Time=w.Stage.Limit-.001f;Tick(w,1,new V());Check(w.State==RunState.Dead&&w.HP==0,"timeout");});
        Test("dash kills enemy and rewards flow",()=>{var w=Empty();var e=new Enemy(new V(.9f,0),0,3,100);w.Stage.Enemies.Add(e);Tick(w,4,new V(1,0),false,true);Check(e.HP<=0&&w.Kills==1&&w.Score==100,"dash kill");});
        Test("kill is awarded exactly once",()=>{var w=Empty();var e=new Enemy(new V(1,0),0,1,100);w.Hit(e,1);w.Hit(e,1);Check(w.Kills==1&&w.Combo==1,"duplicate kill");});
        Test("one dash cannot multiply hit boss every tick",()=>{var w=Empty();var e=new Enemy(new V(3,0),3,65,100){Vulnerable=1};w.Stage.Enemies.Add(e);Tick(w,17,new V(1,0),false,true);Check(e.HP==57,"dash applied more than once "+e.HP);});
        Test("beam telegraphs before activation",()=>{var b=new Beam(new V(-3,0),new V(3,0),0);Check(!b.Active(2.69f)&&b.Warning(2.69f)&&b.Active(2.71f)&&!b.Active(3.61f),"beam schedule");});
        Test("active beam damages and dash bypasses beam",()=>{var w=Empty();w.Stage.Beams.Add(new Beam(new V(-3,0),new V(3,0),0));w.Time=2.8f;Tick(w,1,new V());Check(w.HP==1,"beam harmless");w.Invulnerable=0;Tick(w,1,new V(1,0),false,true);Check(w.HP==1,"dash beam immunity");});
        Test("boss overdrive increases bullet pressure",()=>{var a=Empty();var b=Empty();var ea=new Enemy(new V(7,0),3,60,0);var eb=new Enemy(new V(7,0),3,20,0){CorePhase=2};a.Stage.Enemies.Add(ea);b.Stage.Enemies.Add(eb);Tick(a,1,new V());Tick(b,1,new V());Check(b.Shots.Count>a.Shots.Count&&eb.Clock<ea.Clock,"overdrive absent");});
        Test("core cannot skip its three attack and counter phases",()=>{var w=Empty();var e=new Enemy(new V(7,0),3,60,0);w.Stage.Enemies.Add(e);w.Hit(e,999);Check(e.HP==60,"closed shield ignored");for(int phase=0;phase<3;phase++){e.Clock=0;w.Invulnerable=1;Tick(w,1,new V());Check(e.Attacks==phase+1&&e.Vulnerable>0,"missing pulse");w.Hit(e,999);if(phase<2){Check(e.HP==40-phase*20&&e.Guarding,"phase gate failed");int hp=e.HP;w.Hit(e,999);Check(e.HP==hp,"skipped counter");}}Check(e.HP==0&&e.Attacks==3,"core not defeated");});
        Test("chain expires without aggression",()=>{var w=Empty();w.Hit(new Enemy(new V(),0,1,1),1);Tick(w,400,new V());Check(w.Combo==0&&w.BestCombo==1,"combo timing");});
        Test("relays refill dash and reset parry cooldown",()=>{var w=Empty();w.Player=w.Stage.Seals[0].P;w.Charges=0;w.ParryCooldown=.6f;Tick(w,1,new V());Check(w.Charges==2&&w.SealsTaken==1&&w.ClearReady,"seal reward");});
        Test("parry reflects nearby hostile bullets only",()=>{var w=Empty();w.AddShot(new V(1,1),new V(-1,0),1,false);w.AddShot(new V(5,6),new V(1,0),1,false);w.Tick(Rules.Step,new V(),new V(1,0),false,false,false,true);Check(w.Shots.Count==2&&w.Shots[0].Friendly&&!w.Shots[1].Friendly&&!w.ClearReady,"parry range and ownership");});
        Test("parry cannot be spammed",()=>{var w=Empty();w.Tick(Rules.Step,new V(),new V(),false,false,false,true);Tick(w,20,new V());w.AddShot(new V(1,1),new V(1,0),1,false);w.Tick(Rules.Step,new V(),new V(),false,false,false,true);Check(!w.Shots[0].Friendly,"parry reuse");});
        Test("exit requires both seals and enemies",()=>{var w=new World(0);w.Player=w.Stage.Exit;Tick(w,1,new V());Check(w.State==RunState.Playing,"premature exit");foreach(var s in w.Stage.Seals)s.Taken=true;Tick(w,1,new V());Check(w.State==RunState.Playing,"enemies ignored");foreach(var e in w.Stage.Enemies)e.HP=0;Tick(w,1,new V());Check(w.State==RunState.Won,"exit failed");});
        Test("shooting cadence stays above ten per second",()=>{var w=Empty();int shots=0;w.Event=(kind,p)=>{if(kind=="SHOT")shots++;};Tick(w,120,new V(),true);Check(shots>=10,"fire cadence "+shots);});
        Test("projectile budget is enforced",()=>{var w=Empty();for(int i=0;i<2000;i++)w.AddShot(new V(),new V(1,0),1,false);Check(w.Shots.Count==Rules.MaxBullets,"budget");});
        Test("expired shots are recycled",()=>{var w=Empty();w.AddShot(new V(5,0),new V(),0,true);Tick(w,361,new V());Check(w.Shots.Count==0,"expired bullet leak");});
        Test("reset produces a clean attempt",()=>{var a=new World(5);a.Charges=0;a.Score=999;a.HP=0;var b=new World(5);Check(b.HP==2&&b.Charges==2&&b.Score==0&&b.Time==0&&b.Shots.Count==0,"dirty restart");});
        Test("stage indices are validated",()=>{bool threw=false;try{Stage.Create(6);}catch(ArgumentOutOfRangeException){threw=true;}Check(threw,"invalid index");});
        Test("ribbons require crossing in the marked direction",()=>{var gate=new Seal(0,0,0){Normal=new V(1,0),HalfWidth=1.4f};Check(gate.Crossed(new V(-1,0),new V(1,0)),"forward cut");Check(!gate.Crossed(new V(1,0),new V(-1,0)),"backward cut accepted");Check(!gate.Crossed(new V(-1,2),new V(1,2)),"cut outside ribbon");});
        Test("walking across a ribbon does not count",()=>{var w=new World(1);w.Stage.Enemies.Clear();w.Stage.Walls.Clear();var gate=w.Stage.Seals[0];w.Player=gate.P-gate.Normal*.05f;w.Velocity=gate.Normal*20;w.Tick(Rules.Step,gate.Normal,gate.Normal,false,false,false,false);Check(w.SealsTaken==0,"walk bypassed dash objective");});
        Test("a dash crossing counts a ribbon once",()=>{var w=new World(1);w.Stage.Enemies.Clear();w.Stage.Walls.Clear();var gate=w.Stage.Seals[0];w.Player=gate.P-gate.Normal*.3f;Tick(w,1,gate.Normal,false,true);Check(w.SealsTaken==1&&w.GateCuts==1,"dash cut failed");Tick(w,3,gate.Normal);Check(w.GateCuts==1,"duplicate gate credit");});
        Test("last guard kill and ribbon crossing work in the same tick",()=>{var w=new World(1);w.Stage.Enemies.Clear();w.Stage.Walls.Clear();var gate=w.Stage.Seals[0];gate.P=new V();gate.Normal=new V(1,0);w.Player=new V(-.3f,0);w.Stage.Enemies.Add(new Enemy(new V(.4f,0),1,3,100));Tick(w,1,new V(1,0),false,true);Check(w.Kills==1&&w.SealsTaken==1,"combat and crossing order lost the cut");});
        Test("pursuit checkpoints do not require killing hunters",()=>{var w=new World(4);for(int i=0;i<3;i++){w.Player=w.Stage.Seals[i].P;w.Invulnerable=1;Tick(w,1,new V());}Check(w.SealsTaken==3&&w.Alive>0&&w.ExitOpen,"escape still requires cleanup");w.Player=w.Stage.Exit;w.Invulnerable=1;Tick(w,1,new V());Check(w.State==RunState.Won,"escape exit closed");});
        Test("beam trial breach advances with live enemies",()=>{var w=new World(3);var gate=w.Stage.Seals[0];w.Player=gate.P-gate.Normal*.3f;w.DashLeft=.05f;w.DashDirection=gate.Normal;Tick(w,1,gate.Normal);Check(w.SealsTaken==1&&w.Alive>0,"beam trial still demands elimination");});
        Test("beam warning arms on approach and precedes damage",()=>{var w=new World(3);var beam=w.Stage.Beams[0];Check(!beam.Warning(50)&&!beam.Active(50),"unseen beam armed");w.Player=w.Stage.Seals[0].P-new V(0,5);Tick(w,1,new V());Check(beam.ArmedAt>0&&beam.Warning(w.Time)&&!beam.Active(w.Time),"missing approach warning");Check(beam.Active(w.Time+.91f),"beam never activated");});
        Test("spindle shields reject ordinary fire and dash damage",()=>{var w=Empty();var e=new Enemy(new V(3,0),1,3,100){CounterShield=true};w.Stage.Enemies.Add(e);w.Hit(e,9);Check(e.HP==3,"shield bypassed");Tick(w,8,new V(1,0),false,true);Check(e.HP==3,"dash bypassed counter mechanic");});
        Test("returned fire breaks a spindle shield exactly once",()=>{var w=Empty();var e=new Enemy(new V(4,0),1,3,100){CounterShield=true};w.Stage.Enemies.Add(e);w.AddShot(new V(1,0),new V(-1,0),10,false);w.Tick(Rules.Step,new V(),new V(1,0),false,false,false,true);Tick(w,10,new V());Check(e.HP==0&&w.CounterBreaks==1,"return-fire counter failed");});
        Test("escape completion and mastery are separate",()=>{var w=new World(4);foreach(var s in w.Stage.Seals)s.Taken=true;Check(w.ExitOpen&&!w.MasteryComplete,"plain escape granted mastery");w.RushCounters=3;Check(w.MasteryComplete,"rush counters did not earn mastery");});
        Test("all four boundaries release immediately when moving away",()=>{
            foreach(V direction in new[]{new V(1,0),new V(-1,0),new V(0,1),new V(0,-1)}){
                var w=Empty();w.Player=new V(direction.X*(26-Rules.Radius),direction.Y*(16-Rules.Radius));V start=w.Player;
                Tick(w,12,direction*-1);Check((w.Player-start).Length>1.3f,"sticky face "+direction.X+","+direction.Y);
            }
        });
        Test("dash wall impact allows immediate reverse",()=>{var w=Empty();w.Player=new V(25,0);Tick(w,15,new V(1,0),false,true);float at=w.Player.X;Tick(w,15,new V(-1,0));Check(w.Player.X<at-1,"stuck after impact");});
        Test("near-edge navigation escapes conservative planning margins",()=>{var w=new World(3);V p=new V(21,15.68f),goal=w.Stage.Seals[2].P;for(int i=0;i<240;i++)p=Rules.Move(p,w.Stage.Navigate(p,goal)*.05f,w.Stage.Walls,.52f);Check((p-goal).Length<2,"navigation locked at outer face");});
        Test("dash steering bends but cannot instantly reverse",()=>{var w=Empty();Tick(w,1,new V(1,0),false,true);for(int i=0;i<7;i++)w.Tick(Rules.Step,new V(1,1),new V(1,0),false,false,false,false);Check(w.DashDirection.Y>.1f&&w.DashDirection.X>.8f,"missing controlled bend");V before=w.DashDirection;w.Tick(Rules.Step,new V(-1,0),new V(),false,false,false,false);Check(V.Dot(before,w.DashDirection)>.99f,"instant reversal exploit");});
        Test("dash kill refunds charge but a boss hit does not",()=>{var a=Empty();var b=Empty();a.Stage.Enemies.Add(new Enemy(new V(2,0),1,3,100));b.Stage.Enemies.Add(new Enemy(new V(2,0),3,60,100));Tick(a,8,new V(1,0),false,true);Tick(b,8,new V(1,0),false,true);Check(a.Charges==2&&b.Charges==1,"refund must require kill");});
        Test("front guard blocks while a side shot hits",()=>{
            var a=Empty();var b=Empty();var ea=new Enemy(new V(5,0),0,3,1){Aim=new V(-1,0)};var eb=new Enemy(new V(5,0),0,3,1){Aim=new V(-1,0)};a.Stage.Enemies.Add(ea);b.Stage.Enemies.Add(eb);
            a.AddShot(new V(3,0),new V(1,0),300,true);b.AddShot(new V(5,2),new V(0,-1),300,true);Tick(a,1,new V());Tick(b,1,new V());Check(ea.HP==3&&eb.HP==2,"guard angle");
        });
        Test("guard aim turns through 180 degrees without locking",()=>{V direction=new V(-1,0);for(int i=0;i<240;i++)direction=Rules.Turn(direction,new V(1,0),Rules.Step*2);Check(direction.X>.99f,"opposite-direction aim locked");});
        Test("windup opens frontal guard",()=>{var w=Empty();var e=new Enemy(new V(5,0),0,3,.3f){Aim=new V(-1,0)};w.Stage.Enemies.Add(e);w.AddShot(new V(3,0),new V(1,0),300,true);Tick(w,1,new V());Check(e.HP==2,"no punish window");});
        Test("parry success grants drive and a charge",()=>{var w=Empty();w.Charges=0;w.AddShot(new V(1,0),new V(-1,0),12,false);w.Tick(Rules.Step,new V(),new V(1,0),false,false,false,true);Check(w.Parries==1&&w.Charges==1&&w.Overdrive&&w.Shots[0].Damage==3,"parry reward");});
        Test("parry never reflects through cover",()=>{var w=Empty();w.Stage.Walls.Add(new Wall(.7f,0,.1f,4));w.AddShot(new V(1.5f,0),new V(1,0),1,false);w.Tick(Rules.Step,new V(),new V(1,0),false,false,false,true);Check(!w.Shots[0].Friendly,"reflected through wall");});
        Test("empty parry costs cooldown and expires",()=>{var w=Empty();w.Tick(Rules.Step,new V(),new V(1,0),false,false,false,true);Tick(w,19,new V());Check(w.ParryLeft==0&&w.ParryCooldown>.5f&&w.Parries==0,"free indefinite parry");});
        Test("a reflected shot breaks the front guard",()=>{var w=Empty();var e=new Enemy(new V(5,0),0,3,1){Aim=new V(-1,0)};w.Stage.Enemies.Add(e);w.AddShot(new V(1,0),new V(-1,0),12,false);w.Tick(Rules.Step,new V(),new V(1,0),false,false,false,true);Tick(w,10,new V());Check(e.HP<=0,"parry failed to counter shield");});
        Test("moving graze rewards once without damage",()=>{var w=Empty();w.AddShot(new V(.6f,.72f),new V(1,0),1,false);Tick(w,6,new V(1,0));Check(w.Grazes==1&&w.HP==2&&w.Flow>0,"graze must be close and unique");});
        Test("overdrive increases both movement and shot damage",()=>{var w=Empty();w.Flow=1;Tick(w,15,new V(1,0),true);Near(w.Velocity.Length,24,.01f,"overdrive speed");Check(w.Shots.Count>0&&w.Shots[0].Damage==2,"overdrive shots");});
        Test("idling burns drive faster than moving",()=>{var a=Empty();var b=Empty();a.Flow=b.Flow=1;Tick(a,120,new V());Tick(b,120,new V(1,0));Check(b.Flow>a.Flow+.1f,"no aggression pressure");});
        Test("relays enforce encounter and route order",()=>{var w=new World(0);w.Player=w.Stage.Seals[0].P;Tick(w,1,new V());Check(w.SealsTaken==0,"relay opened with live guards");foreach(var e in w.Stage.Enemies)if(e.Zone==0)e.HP=0;w.Player=w.Stage.Seals[2].P;Tick(w,1,new V());Check(w.SealsTaken==0,"skipped encounter");w.Player=w.Stage.Seals[0].P;Tick(w,1,new V());Check(w.SealsTaken==1&&w.Splits[0]>0,"ordered relay failed");});
        Test("dormant sector does not fire or contact damage",()=>{var w=Empty();var e=new Enemy(new V(.2f,0),0,3,0){Zone=1};w.Stage.Enemies.Add(e);Tick(w,60,new V());Check(w.HP==2&&w.Shots.Count==0,"unannounced next encounter");});
        Test("distant enemy cannot fire unseen",()=>{var w=Empty();w.Stage.Enemies.Add(new Enemy(new V(20,0),1,3,0));Tick(w,100,new V());Check(w.Shots.Count==0,"offscreen shot");});
        Test("hunter routes around a long wall instead of sticking",()=>{var w=Empty();w.Stage.Walls.Add(new Wall(0,0,1,8));w.Player=new V(5,0);var e=new Enemy(new V(-5,0),2,2,100);w.Stage.Enemies.Add(e);for(int i=0;i<480;i++){w.Invulnerable=1;Tick(w,1,new V());}Check(e.P.X>1.5f,"hunter path blocked");});
        Test("damage remembers its source for death explanation",()=>{var w=Empty();w.HP=1;w.Damage("BEAM",new V(-2,1),new V(2,1));Check(w.State==RunState.Dead&&w.DeathCause=="BEAM"&&w.DamageFrom.X==-2,"missing death trace");});
        Test("checkpoint practice restores only completed sectors",()=>{var w=new World(5);w.RestorePractice(2);Check(w.SealsTaken==2&&w.HP==2&&w.Time==0,"practice state");foreach(var e in w.Stage.Enemies)Check(e.Zone<2?e.HP==0:e.HP==e.MaxHP,"incorrect encounter restore");Check((w.Player-w.Stage.Seals[1].P).Length<.01f,"checkpoint spawn");});
        string scratch=Path.Combine(Path.GetDirectoryName(Path.GetFullPath(args.Length>0?args[0]:"model-tests.xml")),"recording-test.bin");
        Test("input recording round trip uses the exact production inputs",()=>{var r=new InputReplay{Stage=2};r.Frames.Add(new ControlFrame(new V(.2f,.7f),new V(-1,0),true,true,false,true));r.Write(scratch);var loaded=InputReplay.Read(scratch);Check(loaded.Stage==2&&loaded.Frames.Count==1&&loaded.Frames[0].Parry&&loaded.Frames[0].Dash,"replay flags");Near(loaded.Frames[0].Move.Y,.7f,0,"input fidelity");});
        Test("truncated input recording is rejected",()=>{File.WriteAllBytes(scratch,new byte[]{1,2,3});bool rejected=false;try{InputReplay.Read(scratch);}catch{rejected=true;}Check(rejected,"corrupt replay accepted");});
        Test("ghost interpolation and persistence agree",()=>{var g=new GhostTrace();var w=Empty();g.Add(w);w.Player=new V(4,0);w.Time=1;g.Add(w);g.Write(scratch);var loaded=GhostTrace.Read(scratch);V p;Check(loaded!=null&&loaded.At(.5f,out p),"ghost load");loaded.At(.5f,out p);Near(p.X,2,.001f,"ghost interpolation");Check(!loaded.At(2,out p),"ghost outlived run");});
        for(int i=0;i<6;i++){
            int index=i;
            Test("stage "+(i+1)+" spawn exit seals and enemies are unobstructed",()=>{var s=Stage.Create(index);Check(!s.Blocked(s.Spawn,.5f),"spawn");Check(!s.Blocked(s.Exit,.5f),"exit");foreach(var p in s.Seals)Check(!s.Blocked(p.P,.7f),"seal");foreach(var e in s.Enemies)Check(!s.Blocked(e.P,.65f),"enemy "+e.P.X+","+e.P.Y);});
            Test("stage "+(i+1)+" all objectives are reachable without wall clipping",()=>{var s=Stage.Create(index);Check(Reachable(s,s.Exit),"unreachable exit");foreach(var p in s.Seals)Check(Reachable(s,p.P),"unreachable seal");foreach(var e in s.Enemies)Check(Reachable(s,e.P),"unreachable enemy");});
            Test("stage "+(i+1)+" deterministic 60 second stress replay",()=>{var a=new World(index);var b=new World(index);a.Stage.Limit=b.Stage.Limit=120;foreach(var e in a.Stage.Enemies)e.Zone=0;foreach(var e in b.Stage.Enemies)e.Zone=0;var random=new Random(810+index);for(int j=0;j<7200;j++){V input=V.Angle((float)random.NextDouble()*6.28f),aim=V.Angle((float)random.NextDouble()*6.28f);a.Invulnerable=b.Invulnerable=1;a.Tick(Rules.Step,input,aim,true,j%90==0,false,j%300==0);b.Tick(Rules.Step,input,aim,true,j%90==0,false,j%300==0);Check(!float.IsNaN(a.Player.X)&&!a.Stage.Blocked(a.Player,Rules.Radius-.005f),"invalid player geometry at "+j);Check(a.Shots.Count<=Rules.MaxBullets,"overflow");}Near(a.Player.X,b.Player.X,0,"nondeterminism");Check(a.Score==b.Score&&a.Shots.Count==b.Shots.Count,"replay mismatch");});
        }
        Test("six authored signatures each contain three encounters",()=>{var names=new HashSet<string>();for(int i=0;i<6;i++){var s=Stage.Create(i);names.Add(s.Signature);for(int zone=0;zone<3;zone++){int count=0;foreach(var e in s.Enemies)if(e.Zone==zone)count++;Check(count>=3,"empty encounter");}Check(s.Route.Count>=8,"missing authored route");}Check(names.Count==6,"duplicate signatures");});
        Test("six minute simulation performance budget",()=>{var timer=Stopwatch.StartNew();for(int stage=0;stage<6;stage++){var w=new World(stage);for(int i=0;i<7200;i++){w.Invulnerable=1;w.Tick(Rules.Step,V.Angle(i*.001f),V.Angle(i*.01f),true,i%90==0,false,false);}}Check(timer.Elapsed.TotalSeconds<12,"simulation too slow "+timer.Elapsed.TotalSeconds);Console.WriteLine("  43,200 ticks in "+timer.ElapsedMilliseconds+" ms");});
        string report="<?xml version=\"1.0\"?><testsuite name=\"Velocity gameplay regression\" tests=\""+(passed+failed)+"\" failures=\""+failed+"\">"+xml+"</testsuite>";File.WriteAllText(args.Length>0?args[0]:"model-tests.xml",report);Console.WriteLine(passed+" passed, "+failed+" failed");return failed==0?0:1;
    }
}
